import{_ as s}from"./chunks/scrollbar-is-code.OgWbhDez.js";import{E as a}from"./chunks/ExampleVirtualScroller.Oz1cSsqe.js";import{W as i,o as l,c as n,aa as t,Y as o,y as c}from"./chunks/framework.Pz9vw46u.js";import"./chunks/theme.Bqo48-vV.js";const f=JSON.parse('{"title":"The scrollbar is code","description":"A 1,000,000-row list where scrolling itself is virtual — Lenis drives position over translateY, the DOM holds a dozen rows, and nothing costs O(total).","frontmatter":{"title":"The scrollbar is code","description":"A 1,000,000-row list where scrolling itself is virtual — Lenis drives position over translateY, the DOM holds a dozen rows, and nothing costs O(total).","date":"2026-07"},"headers":[],"relativePath":"blog/scrollbar-is-code.md","filePath":"blog/scrollbar-is-code.md","lastUpdated":1786381307000}'),h={name:"blog/scrollbar-is-code.md"},w=Object.assign(h,{setup(d){return(m,e)=>{const r=i("ClientOnly");return l(),n("div",null,[e[0]||(e[0]=t('<h1 id="the-scrollbar-is-code" tabindex="-1">The scrollbar is code <a class="header-anchor" href="#the-scrollbar-is-code" aria-label="Permalink to &quot;The scrollbar is code&quot;">​</a></h1><p><img src="'+s+'" alt="The scrollbar is code"></p><p>The browser&#39;s scrollbar has one requirement you cannot negotiate away: to scroll a tall document natively, the DOM has to <em>be</em> tall. At a million rows that means a fifty-million-pixel layer the compositor must carry, native scroll anchoring fighting your virtualization, and physics you don&#39;t control.</p><p>So this million-row list fires the browser from the job. Scrolling is <strong>virtual</strong>: a customized <a href="https://github.com/darkroomengineering/lenis" target="_blank" rel="noreferrer">Lenis</a> owns position, momentum and touch feel, driving a <code>translateY</code> — while the DOM holds a dozen rows between two spacer <code>div</code>s. The scroll range comes from a <em>computed</em> content height, not from the DOM; the compositor layer stays small no matter how long the list claims to be. Wheel through it, jump to the middle, and watch the rows-in-DOM counter hold:</p>',4)),o(r,null,{default:c(()=>[o(a)]),_:1}),e[1]||(e[1]=t('<p>The estimates architecture is the readable part: an item&#39;s position is a prefix sum over measured heights that is <strong>never materialized as an array</strong> — a movable cursor evaluates it lazily, heights are captured one-shot as rows enter and leave the window, and every operation is O(window), never O(total). The jump-to-row landing visibly <em>converges</em> as the fresh window measures in — an estimate refined by reality, in front of you.</p><p>All of it lives on <strong>one ivue class</strong>: template refs, prop refs, scroll state, the windowing math, the Lenis lifecycle — constructed in <code>setup()</code> and torn down by the component scope. This is not a demo component; it&#39;s extracted from production, where it drives feeds this size daily.</p><p>The full tabbed source — the ~1,200-line class included — is on the <a href="/examples/">Examples page</a>, with an Open-in-StackBlitz link that runs the standalone app straight from the repo.</p>',3))])}}});export{f as __pageData,w as default};
